using Namaa.Domain.Entities;using Namaa.Domain.Enums;
namespace Namaa.Application.Quotations.Dtos;
public sealed record QuotationItemDto(long Id,long QuotationId,short LineNumber,string Description,decimal Quantity,decimal UnitPrice,decimal DiscountAmount,decimal TaxAmount,decimal LineTotal,long? ServiceId){internal static QuotationItemDto FromEntity(QuotationItem e)=>new(e.Id,e.QuotationId,e.LineNumber,e.Description,e.Quantity,e.UnitPrice,e.DiscountAmount,e.TaxAmount,e.LineTotal,e.ServiceId);}
public sealed record QuotationPaymentTermDto(long Id,long QuotationId,short InstallmentNumber,string? Description,decimal? Percentage,decimal? Amount,int? DueAfterDays,DateTime? DueDate,DateTime CreatedAt){internal static QuotationPaymentTermDto FromEntity(QuotationPaymentTerm e)=>new(e.Id,e.QuotationId,e.InstallmentNumber,e.Description,e.Percentage,e.Amount,e.DueAfterDays,e.DueDate,e.CreatedAt);}
public sealed record QuotationDto(long Id,long CustomerId,string QuotationNumber,string Title,QuotationStatus Status,DateTime IssueDate,DateTime? ValidUntil,decimal SubTotal,decimal DiscountAmount,decimal TaxAmount,decimal TotalAmount,string? Notes,string? Terms,long CreatedByUserId,DateTime CreatedAt,DateTime? UpdatedAt,IReadOnlyList<QuotationItemDto> Items,IReadOnlyList<QuotationPaymentTermDto> PaymentTerms){internal static QuotationDto FromEntity(Quotation e)=>new(e.Id,e.CustomerId,e.QuotationNumber,e.Title,e.Status,e.IssueDate,e.ValidUntil,e.SubTotal,e.DiscountAmount,e.TaxAmount,e.TotalAmount,e.Notes,e.Terms,e.CreatedByUserId,e.CreatedAt,e.UpdatedAt,e.Items.Select(QuotationItemDto.FromEntity).ToList(),e.PaymentTerms.Select(QuotationPaymentTermDto.FromEntity).ToList());}

